        return dfs(prices, 0, false);
    }
private:
    int dfs(vector<int>& p, int i, bool holding) {
        if (i == (int)p.size()) return holding ? -1000000000 : 0;
        if (holding) {
            int sell = p[i] + dfs(p, i + 1, false);
            int skip = dfs(p, i + 1, true);
            return max(sell, skip);
        } else {
            int buy = -p[i] + dfs(p, i + 1, true);
            int skip = dfs(p, i + 1, false);
            return max(buy, skip);
        }
    }
};

