from typing import List
class Solution:
    def maxProfit(self, prices: List[int]) -> int:
        n = len(prices)
        def dfs(i: int, holding: bool) -> int:
            if i == n:
                return -10**9 if holding else 0
            if holding:
                sell = prices[i] + dfs(i + 1, False)
                skip = dfs(i + 1, True)
                return sell if sell > skip else skip
            else:
                buy = -prices[i] + dfs(i + 1, True)
                skip = dfs(i + 1, False)
                return buy if buy > skip else skip
        return dfs(0, False)

