class Solution {
    public int maxProfit(int[] prices) {
        return dfs(prices, 0, false);
    }
    private int dfs(int[] p, int i, boolean holding) {
        if (i == p.length) return holding ? -1000000000 : 0;
        if (holding) {
            int sell = p[i] + dfs(p, i + 1, false);
            int skip = dfs(p, i + 1, true);
            return Math.max(sell, skip);
        } else {
            int buy = -p[i] + dfs(p, i + 1, true);
            int skip = dfs(p, i + 1, false);
            return Math.max(buy, skip);
        }
    }
}

