class Solution {
public:
    int maxProfit(vector<int>& prices) {
        if (prices.empty()) return 0;
        int hold = -prices[0];
        int cash = 0;
        for (size_t i = 1; i < prices.size(); ++i) {
            int prevHold = hold;
            int prevCash = cash;
            hold = max(prevHold, prevCash - prices[i]);
            cash = max(prevCash, prevHold + prices[i]);
        }
        return cash;
    }
};

