from typing import List
class Solution:
    def maxProfit(self, prices: List[int]) -> int:
        if not prices:
            return 0
        hold = -prices[0]
        cash = 0
        for price in prices[1:]:
            hold, cash = max(hold, cash - price), max(cash, hold + price)
        return cash

