class Solution {
    public int maxProfit(int[] prices) {
        if (prices == null || prices.length == 0) return 0;
        int hold = -prices[0];
        int cash = 0;
        for (int i = 1; i < prices.length; i++) {
            int prevHold = hold;
            int prevCash = cash;
            hold = Math.max(prevHold, prevCash - prices[i]);
            cash = Math.max(prevCash, prevHold + prices[i]);
        }
        return cash;
    }
}

